// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 blockNum, uint256 warpTime) public {
        blockNum = bound(blockNum, 1, 1e6);
        warpTime = bound(warpTime, 1, 1e12);

        vm.roll(blockNum);
        vm.warp(warpTime);
        address sender = makeAddr("sender");
        vm.deal(sender, 20 ether);

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "base call failed");

        bool branchEntered = (blockNum % 15 == 0);

        uint256 expectedBalance = branchEntered ? 0 : 10 ether;

        assertEq(address(c).balance, expectedBalance, "balance invariant violated");
    }
}
